 use FinancialOperations;
 public function __construct(private readonly \PDO $pdo){if(!function_exists('bcadd')||!function_exists('bcsub')||!function_exists('bccomp'))throw new \RuntimeException('bcmath_required');$pdo->exec("SET time_zone='+00:00'");}
 private function q(string $s,array $a=[]):\PDOStatement{$q=$this->pdo->prepare($s);$q->execute($a);return $q;}
 private function id(mixed $v):string{if(!is_string($v)||!preg_match('/\A[A-Za-z0-9_-]{1,64}\z/D',$v))throw new BusinessError('invalid_id');return $v;}
 private function money(mixed $v):string{if(!is_string($v)||!preg_match('/\A(?:0|[1-9][0-9]{0,17})(?:\.[0-9]{1,2})?\z/D',$v)||self::cmp($v,'0')<=0)throw new BusinessError('invalid_amount');[$a,$b]=array_pad(explode('.',$v,2),2,'');$b=str_pad($b,2,'0');if(strlen($a)>18)throw new BusinessError('amount_overflow');return $a.'.'.$b;}
 private static function cents(string $v):string{[$a,$b]=array_pad(explode('.',$v,2),2,'');return ltrim($a.str_pad($b,2,'0'),'0')?:'0';}
 private static function cmp(string $a,string $b):int{$a=self::cents($a);$b=self::cents($b);return strlen($a)<=>strlen($b) ?: strcmp($a,$b);}
 private static function add(string $a,string $b):string{$a=strrev(self::cents($a));$b=strrev(self::cents($b));$n=max(strlen($a),strlen($b));$c=0;$o='';for($i=0;$i<$n;$i++){ $x=(int)($a[$i]??0)+(int)($b[$i]??0)+$c;$o.=($x%10);$c=intdiv($x,10);}if($c)$o.=$c;return strrev($o);}
 private function ctx(string $env,string $kind,string $id):array{if($kind==='sale'){$r=$this->q('SELECT * FROM fin_sales WHERE environment_id=? AND id=? FOR UPDATE',[$env,$id])->fetch();}else{$r=$this->q('SELECT * FROM fin_expenses WHERE environment_id=? AND id=? FOR UPDATE',[$env,$id])->fetch();}if(!$r)throw new BusinessError('reference_not_found',404);return $r;}
 public function execute(string $env,string $op,int $actor,array $cmd):array{
  $this->id($env);if(!preg_match('/\A[A-Za-z0-9_-]{16,100}\z/D',$op))throw new BusinessError('invalid_operation_id');
  if($actor<1)throw new BusinessError('forbidden',403);$json=json_encode($cmd,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);$legacy=hash('sha256',$json);$hash=hash('sha256',json_encode($this->canonical($cmd),JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE));$owns=!$this->pdo->inTransaction();if($owns)$this->pdo->beginTransaction();
  try{if(!$this->q('SELECT id FROM environments WHERE id=? FOR UPDATE',[$env])->fetch())throw new BusinessError('environment_not_found',404);$old=$this->q('SELECT payload_hash,result_json,actor_user_id FROM fin_operation_receipts WHERE environment_id=? AND operation_id=?',[$env,$op])->fetch();if($old){if(!(hash_equals($old['payload_hash'],$hash)||hash_equals($old['payload_hash'],$legacy))||(int)$old['actor_user_id']!==$actor)throw new BusinessError('idempotency_conflict',409);if($owns)$this->pdo->commit();return ['result'=>json_decode($old['result_json'],true),'replayed'=>true];}
   foreach(['discount','commission','tax','refunded'] as $field){foreach([$cmd,$cmd['record']??[]] as $input){if(is_array($input)&&isset($input[$field])&&!preg_match('/\A0(?:\.0+)?\z/D',(string)$input[$field]))throw new BusinessError('unsupported_financial_adjustments',422);}}
   $this->op=$op;$kind=$cmd['kind']??'';if(!in_array($kind,self::KINDS,true))throw new BusinessError('unsupported_financial_operation',422);if($kind==='sale_register'&&isset($cmd['customer']))$this->subscriptionCustomer($env,$this->id($cmd['customer_id']??''),$cmd['customer']);if(!str_starts_with($kind,'subscription_'))$this->guard($env,$kind,$cmd,$op);$r=match($kind){'capital_contribution','withdrawal','treasury_adjustment'=>$this->treasury($env,$cmd),'subscription_register','subscription_renew','subscription_status'=>$this->subscription($env,$cmd),'sale_register'=>$this->sale($env,$cmd),'sale_collect'=>$this->collect($env,$cmd),'cash_refund'=>$this->refund($env,$cmd),'expense_register'=>$this->expense($env,$cmd),'expense_pay'=>$this->pay($env,$cmd),'transfer'=>$this->transfer($env,$cmd),'sale_edit'=>$this->saleEdit($env,$cmd),'sale_void'=>$this->saleVoid($env,$cmd),'sale_refund_commercial'=>$this->saleRefundCommercial($env,$cmd),'expense_edit'=>$this->expenseEdit($env,$cmd),'cash_compensate'=>$this->compensate($env,$cmd),default=>throw new BusinessError('unsupported_financial_operation',422)};if($kind==='sale_register'&&!empty($cmd['lines']))$this->lines($env,(string)$cmd['sale_id'],$cmd['lines'],(string)$cmd['currency']);
   if(isset($cmd['record'])){if(!is_array($cmd['record']))throw new BusinessError('invalid_record');if(in_array($kind,['sale_register','sale_edit'],true))$this->metadata($env,'sale',$cmd['sale_id'],$cmd['record']);elseif(in_array($kind,['expense_register','expense_edit'],true))$this->metadata($env,'expense',$cmd['expense_id'],$cmd['record']);}
   $this->q('INSERT INTO fin_operation_receipts(environment_id,operation_id,actor_user_id,payload_hash,result_json) VALUES(?,?,?,?,?)',[$env,$op,$actor,$hash,json_encode($r,JSON_THROW_ON_ERROR)]);$this->q('INSERT INTO fin_audit(environment_id,operation_id,actor_user_id,event,payload_json) VALUES(?,?,?,?,?)',[$env,$op,$actor,$kind,$json]);if($owns)$this->pdo->commit();return ['result'=>$r,'replayed'=>false];
  }catch(\Throwable $e){if($owns&&$this->pdo->inTransaction())$this->pdo->rollBack();if($e instanceof \PDOException){if($e->getCode()==='23000')throw new BusinessError('integrity_conflict',409);throw new BusinessError('storage_error',503);}throw $e;}
 }
 /** One existing executor, atomic across an explicitly reviewed historical group. */
 public function executeBatch(string $env,int $actor,array $commands,bool $preview=false,?callable $precondition=null,?callable $postcondition=null):array {
  if($this->pdo->inTransaction()||!$commands||count($commands)>1000)throw new BusinessError('invalid_financial_batch');
  $this->pdo->beginTransaction();
  try{if(!$this->q('SELECT id FROM environments WHERE id=? FOR UPDATE',[$env])->fetch())throw new BusinessError('environment_not_found',404);if($precondition)$precondition();$results=[];foreach($commands as $entry)$results[]=$this->execute($env,$entry['operation_id'],$actor,$entry['command']);
   if($postcondition)$postcondition($results);if($preview)$this->pdo->rollBack();else $this->pdo->commit();return $results;
  }catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
 }
 private const KINDS=['capital_contribution','withdrawal','treasury_adjustment','subscription_register','subscription_renew','subscription_status','sale_register','sale_collect','cash_refund','expense_register','expense_pay','transfer','sale_edit','sale_void','sale_refund_commercial','expense_edit','cash_compensate'];
 private function canonical(mixed $v):mixed{if(!is_array($v))return $v;if(!array_is_list($v))ksort($v,SORT_STRING);return array_map([$this,'canonical'],$v);}
 private function validDate(mixed $v):string{if(!is_string($v)||!preg_match('/\A\d{4}-\d{2}-\d{2}\z/D',$v))throw new BusinessError('invalid_date');$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v||substr($v,0,4)<'1000')throw new BusinessError('invalid_date');return $v;}
 private function refCurrency(string $e,mixed $v):void{$id=$this->id($v);if(!$this->q('SELECT id FROM currencies WHERE environment_id=? AND id=?',[$e,$id])->fetch())throw new BusinessError('currency_reference_invalid',422);}
 private function refCustomer(string $e,mixed $v):void{if($v===null)return;$id=$this->id($v);if(!$this->q('SELECT id FROM customers WHERE environment_id=? AND id=?',[$e,$id])->fetch())throw new BusinessError('customer_reference_invalid',422);}
 private function accountCurrency(string $e,mixed $v):string{$r=$this->q('SELECT currency_id FROM accounts WHERE environment_id=? AND id=? FOR UPDATE',[$e,$this->id($v)])->fetchColumn();if($r===false)throw new BusinessError('account_reference_invalid',422);return (string)$r;}
 private function guard(string $e,string $kind,array $cmd,string $op):void{
  $create=in_array($kind,['sale_register','expense_register'],true);$context=[];
  if(in_array($kind,['sale_collect','cash_refund','sale_edit','sale_void','sale_refund_commercial'],true)){$s=$this->ctx($e,'sale',$this->id($cmd['sale_id']??''));$used=(string)$this->q('SELECT COALESCE(SUM(amount),0) FROM fin_sale_allocations WHERE environment_id=? AND sale_id=?',[$e,$s['id']])->fetchColumn();$context+=['status'=>$s['status'],'version'=>(int)$s['row_version'],'entity_currency'=>$s['currency_id'],'pay_status'=>bccomp($used,(string)$s['total'],2)>=0?'cobrado':'pendiente'];}
  elseif(in_array($kind,['expense_pay','expense_edit'],true)){$x=$this->ctx($e,'expense',$this->id($cmd['expense_id']??''));$context+=['status'=>$x['status'],'version'=>(int)$x['row_version'],'entity_currency'=>$x['currency_id']];}
  elseif($create&&is_string($cmd['currency']??null))$context['entity_currency']=$cmd['currency'];
  // A transfer has no versioned row; its version check is delegated to the client's expected_version (documented limit).
  elseif(in_array($kind,['transfer','cash_compensate','capital_contribution','withdrawal','treasury_adjustment'],true))$context['version']=is_int($cmd['expected_version']??null)?$cmd['expected_version']:0;
  if($kind==='cash_compensate')$context['entity_currency']=$this->movementCurrency($e,$cmd['original_movement_id']??'');
  if(is_string($cmd['account_id']??null))$context['account_currency']=$this->accountCurrency($e,$cmd['account_id']);
  if(is_string($cmd['destination_account_id']??null))$context['destination_account_currency']=$this->accountCurrency($e,$cmd['destination_account_id']);
  $envelope=[...$cmd,'kind'=>$kind,'operation_id'=>$op,'expected_version'=>$cmd['expected_version']??($create?0:($context['version']??0))];
  try{FinancialContracts::describe($envelope,$context);}catch(\InvalidArgumentException $x){throw new BusinessError($x->getMessage(),$x->getMessage()==='version_conflict'?409:422);}
  if($create)$this->refCurrency($e,$cmd['currency']??'');
  if($kind==='sale_register')$this->refCustomer($e,$cmd['customer_id']??null);
  if(in_array($kind,['sale_register','expense_register','sale_collect','cash_refund','expense_pay','transfer','cash_compensate','capital_contribution','withdrawal','treasury_adjustment'],true))$this->validDate($cmd['date']??'');
 }
  private string $op='';
 private function collectedOn(string $e,string $sid):string{return (string)$this->q('SELECT COALESCE(SUM(amount),0) FROM fin_sale_allocations WHERE environment_id=? AND sale_id=?',[$e,$sid])->fetchColumn();}
 private function nextRevision(string $e,string $table,string $key,string $id):int{return (int)$this->q("SELECT COALESCE(MAX(revision_no),0)+1 FROM $table WHERE environment_id=? AND $key=?",[$e,$id])->fetchColumn();}
 private function movementCurrency(string $e,mixed $v):string{$r=$this->q('SELECT currency_id FROM fin_movements WHERE environment_id=? AND id=? FOR UPDATE',[$e,$this->id($v)])->fetchColumn();if($r===false)throw new BusinessError('reference_not_found',404);return (string)$r;}
 private function saleEdit(string $e,array $c):array{$sid=$this->id($c['sale_id']??'');$s=$this->ctx($e,'sale',$sid);
  $detailsOnly=!array_key_exists('amount',$c)&&!array_key_exists('customer_id',$c)&&!array_key_exists('lines',$c)&&isset($c['record']);
  if($detailsOnly){$rev=$this->nextRevision($e,'fin_sale_revisions','sale_id',$sid);$paid=$this->collectedOn($e,$sid);$this->q('INSERT INTO fin_sale_revisions(environment_id,sale_id,revision_no,operation_id,kind,previous_total,new_total,amount,status_before,status_after,collected_at_revision) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$e,$sid,$rev,$this->op,'edit',$s['total'],$s['total'],null,$s['status'],$s['status'],$paid]);$this->q('UPDATE fin_sales SET row_version=row_version+1 WHERE environment_id=? AND id=?',[$e,$sid]);return ['sale_id'=>$sid,'revision'=>$rev,'row_version'=>(int)$s['row_version']+1,'cash_effect'=>false];}
  if(bccomp($this->collectedOn($e,$sid),'0',2)>0)throw new BusinessError('sale_has_collections',422);
  $hasLines=array_key_exists('lines',$c);$oldLines=$this->q('SELECT line_no,product_id,version_id,description,quantity,unit_price,line_total FROM fin_sale_lines WHERE environment_id=? AND sale_id=? ORDER BY line_no',[$e,$sid])->fetchAll(\PDO::FETCH_ASSOC);
  if($hasLines&&!is_array($c['lines']))throw new BusinessError('invalid_sale_lines');
  if(!$hasLines&&$oldLines)throw new BusinessError('sale_lines_required_for_edit');
  $new=$this->money($c['amount']??'');$customer=array_key_exists('customer_id',$c)?$c['customer_id']:$s['customer_id'];$this->refCustomer($e,$customer);
  $newLines=$hasLines?$this->validateLines($e,$c['lines'],(string)$s['currency_id']):null;
  if($hasLines&&bccomp($newLines['sum'],$new,2)!==0)throw new BusinessError('sale_lines_total_mismatch');
  $rev=$this->nextRevision($e,'fin_sale_revisions','sale_id',$sid);
  $this->q('INSERT INTO fin_sale_revisions(environment_id,sale_id,revision_no,operation_id,kind,previous_total,new_total,amount,status_before,status_after,collected_at_revision) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$e,$sid,$rev,$this->op,'edit',(string)$s['total'],$new,null,'valida','valida','0.00']);
  if($hasLines){$this->q('INSERT INTO fin_sale_line_revisions(environment_id,sale_id,revision_no,operation_id,lines_json) VALUES(?,?,?,?,?)',[$e,$sid,$rev,$this->op,json_encode($oldLines,JSON_THROW_ON_ERROR)]);$this->q('DELETE FROM fin_sale_lines WHERE environment_id=? AND sale_id=?',[$e,$sid]);foreach($newLines['rows'] as $line)$this->q('INSERT INTO fin_sale_lines(environment_id,sale_id,line_no,product_id,version_id,description,quantity,unit_price,line_total) VALUES(?,?,?,?,?,?,?,?,?)',[$e,$sid,$line['line_no'],$line['product_id'],$line['version_id'],$line['description'],$line['quantity'],$line['unit_price'],$line['line_total']]);}
  $this->q('UPDATE fin_sales SET total=?,customer_id=?,row_version=row_version+1,updated_at=CURRENT_TIMESTAMP(6) WHERE environment_id=? AND id=?',[$new,$customer,$e,$sid]);
  return ['sale_id'=>$sid,'previous_total'=>(string)$s['total'],'total'=>$new,'revision'=>$rev,'row_version'=>(int)$s['row_version']+1,'lines_replaced'=>$hasLines];}
 private function saleVoid(string $e,array $c):array{$sid=$this->id($c['sale_id']??'');$s=$this->ctx($e,'sale',$sid);$collected=$this->collectedOn($e,$sid);$rev=$this->nextRevision($e,'fin_sale_revisions','sale_id',$sid);
  $this->q('INSERT INTO fin_sale_revisions(environment_id,sale_id,revision_no,operation_id,kind,previous_total,new_total,amount,status_before,status_after,collected_at_revision) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$e,$sid,$rev,$this->op,'void',(string)$s['total'],null,null,'valida','anulada',$collected]);
  $this->q("UPDATE fin_sales SET status='anulada',row_version=row_version+1,updated_at=CURRENT_TIMESTAMP(6) WHERE environment_id=? AND id=?",[$e,$sid]);
  return ['sale_id'=>$sid,'status'=>'anulada','collected'=>$collected,'cash_regularization_warning'=>bccomp($collected,'0',2)>0,'revision'=>$rev];}
 private function saleRefundCommercial(string $e,array $c):array{$sid=$this->id($c['sale_id']??'');$s=$this->ctx($e,'sale',$sid);$amt=$this->money($c['amount']??'');
  $collected=$this->collectedOn($e,$sid);$already=(string)$this->q("SELECT COALESCE(SUM(amount),0) FROM fin_sale_revisions WHERE environment_id=? AND sale_id=? AND kind='refund_commercial'",[$e,$sid])->fetchColumn();
  if(bccomp(bcadd($already,$amt,2),$collected,2)>0)throw new BusinessError('commercial_refund_exceeds_collected',422);
