  $this->q('UPDATE fin_sales SET row_version=row_version+1 WHERE environment_id=? AND id=?',[$e,$sid]);return ['sale_id'=>$sid,'revision'=>$rev,'amount'=>$amt,'cash_effect'=>false,'status'=>'valida'];}
 private function expenseEdit(string $e,array $c):array{$id=$this->id($c['expense_id']??'');$x=$this->ctx($e,'expense',$id);if($x['status']==='anulado')throw new BusinessError('expense_state_conflict',422);
  $new=$this->money($c['amount']??'');$paid=(string)$this->q('SELECT COALESCE(SUM(amount),0) FROM fin_expense_allocations WHERE environment_id=? AND expense_id=?',[$e,$id])->fetchColumn();
  $cur=array_key_exists('currency',$c)?$this->id($c['currency']):$x['currency_id'];$date=array_key_exists('date',$c)?$this->validDate($c['date']):$x['incurred_on'];$supplier=array_key_exists('supplier_id',$c)?$c['supplier_id']:$x['supplier_id'];
  if($cur!==$x['currency_id']&&bccomp($paid,'0',2)>0)throw new BusinessError('expense_currency_has_payments',422);
  $this->refCurrency($e,$cur);if($supplier!==null&&!$this->q('SELECT id FROM suppliers WHERE environment_id=? AND id=? AND archived_at IS NULL',[$e,$this->id($supplier)])->fetch())throw new BusinessError('supplier_reference_invalid');
  if(bccomp($new,$paid,2)<0)throw new BusinessError('expense_total_below_paid',422);
  $status=bccomp($paid,$new,2)===0?'pagado':($x['status']==='vencido'?'vencido':'pendiente');
  $rev=$this->nextRevision($e,'fin_expense_revisions','expense_id',$id);
  $this->q('INSERT INTO fin_expense_revisions(environment_id,expense_id,revision_no,operation_id,kind,previous_total,new_total,status_before,status_after,paid_at_revision) VALUES(?,?,?,?,?,?,?,?,?,?)',[$e,$id,$rev,$this->op,'edit',(string)$x['total'],$new,$x['status'],$status,$paid]);
  $this->q('UPDATE fin_expenses SET total=?,status=?,currency_id=?,incurred_on=?,supplier_id=?,row_version=row_version+1,updated_at=CURRENT_TIMESTAMP(6) WHERE environment_id=? AND id=?',[$new,$status,$cur,$date,$supplier,$e,$id]);
  return ['expense_id'=>$id,'previous_total'=>(string)$x['total'],'total'=>$new,'status'=>$status,'paid'=>$paid,'revision'=>$rev,'row_version'=>(int)$x['row_version']+1,'previous_details'=>['currency'=>$x['currency_id'],'date'=>$x['incurred_on'],'supplier_id'=>$x['supplier_id']]];}
 private function compensate(string $e,array $c):array{$orig=$this->id($c['original_movement_id']??'');
  $m=$this->q('SELECT * FROM fin_movements WHERE environment_id=? AND id=? FOR UPDATE',[$e,$orig])->fetch();
  if(!$m)throw new BusinessError('reference_not_found',404);
  if(!in_array($m['kind'],['receipt','refund','payment'],true))throw new BusinessError('compensation_not_allowed',422);
  $done=(string)$this->q('SELECT COALESCE(SUM(amount),0) FROM fin_movements WHERE environment_id=? AND reversal_of=?',[$e,$orig])->fetchColumn();
  $remaining=bcsub((string)$m['amount'],$done,2);$amt=$this->money($c['amount']??'');
  if(bccomp($amt,$remaining,2)>0)throw new BusinessError('over_compensation',422);
  $this->account($e,$this->id($c['account_id']??''),(string)$m['currency_id']);
  $mid=$this->id($c['movement_id']??('mv_'.bin2hex(random_bytes(8))));$dir=$m['direction']==='in'?'out':'in';
  $this->q('INSERT INTO fin_movements(environment_id,id,account_id,kind,direction,amount,currency_id,movement_on,sale_id,expense_id,reference_id,reversal_of) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[$e,$mid,$c['account_id'],'compensation',$dir,$amt,$m['currency_id'],$c['date'],$m['sale_id'],$m['expense_id'],$mid,$orig]);
  return ['movement_id'=>$mid,'original_movement_id'=>$orig,'amount'=>$amt,'direction'=>$dir,'remaining_after'=>bcsub($remaining,$amt,2)];}
 private function account(string $e,string $id,string $cur):void{if(!$this->q('SELECT id FROM accounts WHERE environment_id=? AND id=? AND currency_id=? FOR UPDATE',[$e,$id,$cur])->fetch())throw new BusinessError('account_reference_invalid',422);}
 private function lines(string $e,string $sale,array $lines,string $currency):void{$saleRow=$this->q('SELECT total FROM fin_sales WHERE environment_id=? AND id=? FOR UPDATE',[$e,$sale])->fetch();if(!$saleRow)throw new BusinessError('sale_not_found',404);$sum='0';foreach($lines as $i=>$line){if(!is_array($line)||!is_int($i))throw new BusinessError('invalid_sale_line');$product=$line['product_id']??null;$version=$line['version_id']??null;if($product!==null){$p=$this->q('SELECT archived_at FROM products WHERE environment_id=? AND id=? FOR UPDATE',[$e,$product])->fetch();if(!$p)throw new BusinessError('product_not_found',404);if($p['archived_at']!==null)throw new BusinessError('product_archived');if($version!==null){$v=$this->q('SELECT product_id,archived_at,currency_id,price FROM product_versions WHERE environment_id=? AND id=? FOR UPDATE',[$e,$version])->fetch();if(!$v||$v['product_id']!==$product||$v['archived_at']!==null||$v['currency_id']!==$currency)throw new BusinessError('version_reference_invalid');}}elseif($version!==null)throw new BusinessError('version_requires_product');$qty=$line['quantity']??null;$unit=$line['unit_price']??null;$total=$line['line_total']??null;if(!is_string($qty)||!preg_match('/\A(?:0|[1-9][0-9]{0,17})(?:\.[0-9]{1,6})?\z/D',$qty)||self::cmp($qty,'0')<=0||!is_string($unit)||!is_string($total))throw new BusinessError('invalid_sale_line_amount');$unit=$this->money($unit);$total=$this->money($total);$expected=bcmul($qty,$unit,8);if(bccomp($expected,$total,8)!==0)throw new BusinessError('line_total_mismatch');$sum=bcadd($sum,$total,2);$this->q('INSERT INTO fin_sale_lines(environment_id,sale_id,line_no,product_id,version_id,description,quantity,unit_price,line_total) VALUES(?,?,?,?,?,?,?,?,?)',[$e,$sale,$i,$product,$version,(string)($line['description']??''),$qty,$unit,$total]);}if(bccomp($sum,(string)$saleRow['total'],2)!==0)throw new BusinessError('sale_lines_total_mismatch');}
 private function validateLines(string $e,array $lines,string $currency):array{$rows=[];$sum='0';foreach($lines as $i=>$line){if(!is_array($line)||!is_int($i))throw new BusinessError('invalid_sale_line');$product=$line['product_id']??null;$version=$line['version_id']??null;if($product!==null){$product=$this->id($product);$p=$this->q('SELECT archived_at FROM products WHERE environment_id=? AND id=? FOR UPDATE',[$e,$product])->fetch();if(!$p)throw new BusinessError('product_not_found',404);if($p['archived_at']!==null)throw new BusinessError('product_archived');if($version!==null){$version=$this->id($version);$v=$this->q('SELECT product_id,archived_at,currency_id FROM product_versions WHERE environment_id=? AND id=? FOR UPDATE',[$e,$version])->fetch();if(!$v||$v['product_id']!==$product||$v['archived_at']!==null||$v['currency_id']!==$currency)throw new BusinessError('version_reference_invalid');}}elseif($version!==null)throw new BusinessError('version_requires_product');$qty=$line['quantity']??null;$unit=$line['unit_price']??null;$total=$line['line_total']??null;if(!is_string($qty)||!preg_match('/\A(?:0|[1-9][0-9]{0,17})(?:\.[0-9]{1,6})?\z/D',$qty)||self::cmp($qty,'0')<=0||!is_string($unit)||!is_string($total))throw new BusinessError('invalid_sale_line_amount');$unit=$this->money($unit);$total=$this->money($total);if(bccomp(bcmul($qty,$unit,8),$total,8)!==0)throw new BusinessError('line_total_mismatch');$sum=bcadd($sum,$total,2);$rows[]=['line_no'=>$i,'product_id'=>$product,'version_id'=>$version,'description'=>(string)($line['description']??''),'quantity'=>$qty,'unit_price'=>$unit,'line_total'=>$total];}if(!$rows)throw new BusinessError('sale_lines_required');return ['rows'=>$rows,'sum'=>$sum];}
 private function sale(string $e,array $c):array{$id=$this->id($c['sale_id']??'');$cur=$this->id($c['currency']??'');$total=$this->money($c['amount']??'');$this->q('INSERT INTO fin_sales(environment_id,id,customer_id,currency_id,total,issued_on) VALUES(?,?,?,?,?,?)',[$e,$id,$c['customer_id']??null,$cur,$total,$c['date']??'']);if(($c['settle_now']??false)===true){$c['sale_id']=$id;$c['amount']=$total;$c['date']=$this->validDate($c['payment_date']??$c['date']);return ['sale_id'=>$id,'settled'=>$this->collect($e,$c)];}return ['sale_id'=>$id,'status'=>'valida'];}
 private function collect(string $e,array $c):array{$sid=$this->id($c['sale_id']??'');$s=$this->ctx($e,'sale',$sid);$amt=$this->money($c['amount']??'');$this->account($e,$this->id($c['account_id']??''),$s['currency_id']);$used=(string)$this->q('SELECT COALESCE(SUM(amount),0) FROM fin_sale_allocations WHERE environment_id=? AND sale_id=?',[$e,$sid])->fetchColumn();if(bccomp(bcadd($used,$amt,2),$s['total'],2)>0)throw new BusinessError('over_collection',422);$mid=$this->id($c['movement_id']??('mv_'.bin2hex(random_bytes(8))));$this->q('INSERT INTO fin_movements(environment_id,id,account_id,kind,direction,amount,currency_id,movement_on,sale_id,reference_id) VALUES(?,?,?,?,?,?,?,?,?,?)',[$e,$mid,$c['account_id'],'receipt','in',$amt,$s['currency_id'],$c['date'],$sid,$c['operation_id']??$mid]);$this->q('INSERT INTO fin_sale_allocations VALUES(?,?,?,?)',[$e,$sid,$mid,$amt]);$this->q('UPDATE fin_sales SET row_version=row_version+1 WHERE environment_id=? AND id=?',[$e,$sid]);return ['sale_id'=>$sid,'movement_id'=>$mid,'amount'=>$amt];}
 private function refund(string $e,array $c):array{$sid=$this->id($c['sale_id']??'');$s=$this->ctx($e,'sale',$sid);$amt=$this->money($c['amount']??'');$this->account($e,$this->id($c['account_id']??''),$s['currency_id']);$in=(string)$this->q("SELECT COALESCE(SUM(a.amount),0) FROM fin_sale_allocations a JOIN fin_movements m ON m.environment_id=a.environment_id AND m.id=a.movement_id WHERE a.environment_id=? AND a.sale_id=? AND m.direction='in'",[$e,$sid])->fetchColumn();$out=(string)$this->q("SELECT COALESCE(SUM(CASE WHEN kind='refund' OR (kind='compensation' AND direction='out') THEN amount WHEN kind='compensation' AND direction='in' THEN -amount ELSE 0 END),0) FROM fin_movements WHERE environment_id=? AND sale_id=? AND kind IN ('refund','compensation')",[$e,$sid])->fetchColumn();if(bccomp(bcadd($out,$amt,2),$in,2)>0)throw new BusinessError('over_refund',422);$mid=$this->id($c['movement_id']??('mv_'.bin2hex(random_bytes(8))));$this->q('INSERT INTO fin_movements(environment_id,id,account_id,kind,direction,amount,currency_id,movement_on,sale_id,reference_id) VALUES(?,?,?,?,?,?,?,?,?,?)',[$e,$mid,$c['account_id'],'refund','out',$amt,$s['currency_id'],$c['date'],$sid,$c['operation_id']??$mid]);$this->q('UPDATE fin_sales SET row_version=row_version+1 WHERE environment_id=? AND id=?',[$e,$sid]);return ['sale_id'=>$sid,'movement_id'=>$mid,'amount'=>$amt];}
 private function expense(string $e,array $c):array{$id=$this->id($c['expense_id']??'');$cur=$this->id($c['currency']??'');$amt=$this->money($c['amount']??'');if(!empty($c['supplier_id'])&&!$this->q('SELECT id FROM suppliers WHERE environment_id=? AND id=? AND archived_at IS NULL',[$e,$this->id($c['supplier_id'])])->fetch())throw new BusinessError('supplier_reference_invalid');$this->q('INSERT INTO fin_expenses(environment_id,id,currency_id,total,incurred_on,supplier_id) VALUES(?,?,?,?,?,?)',[$e,$id,$cur,$amt,$c['date']??'',$c['supplier_id']??null]);if(($c['settle_now']??false)===true){$c['expense_id']=$id;$c['date']=$this->validDate($c['payment_date']??$c['date']);return ['expense_id'=>$id,'settled'=>$this->pay($e,$c)];}return ['expense_id'=>$id,'status'=>'pendiente'];}
 private function pay(string $e,array $c):array{$id=$this->id($c['expense_id']??'');$x=$this->ctx($e,'expense',$id);$amt=$this->money($c['amount']??'');$this->account($e,$this->id($c['account_id']??''),$x['currency_id']);$used=(string)$this->q('SELECT COALESCE(SUM(amount),0) FROM fin_expense_allocations WHERE environment_id=? AND expense_id=?',[$e,$id])->fetchColumn();if(bccomp(bcadd($used,$amt,2),$x['total'],2)>0)throw new BusinessError('over_payment',422);$mid=$this->id($c['movement_id']??('mv_'.bin2hex(random_bytes(8))));$this->q('INSERT INTO fin_movements(environment_id,id,account_id,kind,direction,amount,currency_id,movement_on,expense_id,reference_id) VALUES(?,?,?,?,?,?,?,?,?,?)',[$e,$mid,$c['account_id'],'payment','out',$amt,$x['currency_id'],$c['date'],$id,$c['operation_id']??$mid]);$this->q('INSERT INTO fin_expense_allocations VALUES(?,?,?,?)',[$e,$id,$mid,$amt]);$paid=bcadd($used,$amt,2);$status=bccomp($paid,(string)$x['total'],2)===0?'pagado':$x['status'];$this->q('UPDATE fin_expenses SET status=?,row_version=row_version+1,updated_at=CURRENT_TIMESTAMP(6) WHERE environment_id=? AND id=?',[$status,$e,$id]);return ['expense_id'=>$id,'movement_id'=>$mid,'amount'=>$amt,'status'=>$status,'paid'=>$paid,'pending'=>bcsub((string)$x['total'],$paid,2),'row_version'=>(int)$x['row_version']+1];}
 private function transfer(string $e,array $c):array{$a=$this->id($c['account_id']??'');$b=$this->id($c['destination_account_id']??'');$cur=$this->id($c['currency']??'');$dcur=$this->id($c['destination_currency']??'');$amt=$this->money($c['amount']??'');$damt=$this->money($c['destination_amount']??'');$this->account($e,$a,$cur);$this->account($e,$b,$dcur);$ref=$this->id($c['reference_id']??('tr_'.bin2hex(random_bytes(8))));$m1=$this->id($c['source_movement_id']??('mv_'.bin2hex(random_bytes(8))));$m2=$this->id($c['destination_movement_id']??('mv_'.bin2hex(random_bytes(8))));$this->q('INSERT INTO fin_movements(environment_id,id,account_id,kind,direction,amount,currency_id,movement_on,reference_id) VALUES(?,?,?,?,?,?,?,?,?)',[$e,$m1,$a,'transfer','out',$amt,$cur,$c['date'],$ref]);$this->q('INSERT INTO fin_movements(environment_id,id,account_id,kind,direction,amount,currency_id,movement_on,reference_id) VALUES(?,?,?,?,?,?,?,?,?)',[$e,$m2,$b,'transfer','in',$damt,$dcur,$c['date'],$ref]);return ['source_movement_id'=>$m1,'destination_movement_id'=>$m2];}
}
